import * as React from 'react';
import type { CSSProperties } from 'react';
import { ChevronDown, ChevronRight, CheckIcon, Loader2, MinusIcon, XIcon } from 'lucide-react';

import { Button } from '../../ui/actions/button';
import { Badge } from '../../ui/display/badge';
import { Separator } from '../../ui/display/separator';
import { Popover, PopoverContent, PopoverTrigger } from '../../ui/overlays/popover';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '../../ui/forms/command';
import { cn } from '../../../lib/utils';

import type {
  TreeSelectInnerProps,
  TreeSelectProps,
  TreeMultipleSelectProps,
  TreeSelectRef,
  TreeSelectItem,
} from './types';
import { useGetScreenConfigTreeSelect } from './hooks/use-get-screen-size';
import { useTreeSelectLogic } from './hooks/use-tree-select-logic';
import { useTreeSelectVirtual } from './hooks/use-tree-select-virtualize';
import { SelectedBadgeNode } from '../selected-badge-node/component';
import { LongText } from '../long-text';
import { suppressScrollOnFocus } from '../../../lib/suppress-scroll-on-focus';
import { cva } from 'class-variance-authority';

const DEFAULT_MAX_COUNT = 3;

/**
 * Variants for the multi-select component to handle different styles.
 * Uses class-variance-authority (cva) to define different styles based on "variant" prop.
 */
export const treeSelectVariants = cva('mx-1 transition-all duration-300 ease-in-out', {
  variants: {
    variant: {
      default: 'border-foreground/10 bg-card text-foreground hover:bg-card/80',
      secondary:
        'border-foreground/10 bg-secondary text-secondary-foreground hover:bg-secondary/80',
      destructive:
        'border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80',
      inverted: 'inverted',
    },
    badgeAnimation: {
      bounce: 'hover:-translate-y-1 hover:scale-110',
      pulse: 'hover:animate-pulse',
      wiggle: 'hover:animate-wiggle',
      fade: 'hover:opacity-80',
      slide: 'hover:translate-x-1',
      none: '',
    },
  },
  defaultVariants: {
    variant: 'default',
    badgeAnimation: 'bounce',
  },
});

type SelectedTreeItemNodeProps = {
  label: string;
  badgeLabelMaxWidth: string;
  onRemove?: () => void;
  badgeClassName?: string;
  badgeStyle?: CSSProperties;
  compactMode?: boolean;
  iconClassName?: string;
};

const SelectedTreeItemNode: React.FC<SelectedTreeItemNodeProps> = ({
  label,
  badgeLabelMaxWidth,
  onRemove,
  badgeClassName,
  badgeStyle,
  compactMode,
  iconClassName,
}) => {
  if (!onRemove) {
    return (
      <Badge className="h-6 shrink-0 whitespace-nowrap rounded-sm bg-card text-foreground text-xs">
        <span className="block max-w-full overflow-hidden text-ellipsis whitespace-nowrap leading-normal">
          {label}
        </span>
      </Badge>
    );
  }

  return (
    <SelectedBadgeNode
      label={label}
      badgeLabelMaxWidth={badgeLabelMaxWidth}
      badgeClassName={badgeClassName}
      badgeStyle={badgeStyle}
      iconClassName={iconClassName}
      compactMode={compactMode}
      onRemove={onRemove}
      removeAriaLabel={`Remove ${label}`}
    />
  );
};

const TreeSelectInner = React.forwardRef<TreeSelectRef, TreeSelectInnerProps>(
  (
    {
      className,
      responsive,
      disabled,
      multiple,
      placeholder = 'Select',
      disableClear,
      defaultValue,
      value,
      onChange,
      onOpenChange,
      loadOptions,
      debounceMs,
      disableSelectAll,
      autoSize,
      triggerClassName,
      popoverClassName,
      modalPopover,
      minWidth,
      maxWidth,
      badgeLabelMaxWidth = '100%',
      optionLabelMaxWidth = '100%',
      estimateSize = 32,
      enableVirtualization,
      loadingText = 'Loading options...',
      loadingMoreText = 'Loading more...',
      emptyIndicator,
      isLoading,
      searchable,
      treeData,
      maxCount = DEFAULT_MAX_COUNT,
      defaultSelectAll,
      popoverMaxHeight,
      defaultExpandAll,
      animation,
      animationConfig,
      variant = 'default',
      badgeAnimation,
      singleLine,
    },
    ref
  ) => {
    const listRef = React.useRef<HTMLDivElement>(null);
    const buttonRef = React.useRef<HTMLButtonElement>(null);
    const [observerRoot, setObserverRoot] = React.useState<HTMLDivElement | null>(null);
    const [isPopoverOpen, setIsPopoverOpen] = React.useState(false);

    const handleListRef = React.useCallback((node: HTMLDivElement | null) => {
      listRef.current = node;
      setObserverRoot(node);
    }, []);

    const treeLogic = useTreeSelectLogic({
      treeData,
      multiple,
      value,
      defaultValue,
      // Normalize onChange so the hook always works with `string[]`
      // while the public API exposes single vs multi signatures.
      onChange: (nextValues: string[], selectedNodes: TreeSelectItem[]) => {
        if (!onChange) return;
        if (multiple) {
          (onChange as TreeMultipleSelectProps['onChange'] | undefined)?.(
            nextValues ?? [],
            selectedNodes
          );
          return;
        }
        const safeValues = nextValues ?? [];
        const firstValue = safeValues.length > 0 ? safeValues[0] : null;
        const firstNode = selectedNodes[0];
        const nextValue: string | null = firstValue as string | null;
        (onChange as TreeSelectProps['onChange'] | undefined)?.(nextValue, firstNode);
      },
      loadOptions,
      debounceMs,
      defaultExpandAll,
      observerRoot,
      isOpen: isPopoverOpen,
    });
    const {
      selectedValues,
      searchValue,
      setSearchValue,
      rows,
      selectionMap,
      toggleNode,
      toggleAll,
      clear,
      getLabelForValue,
      isAsyncMode,
      asyncData,
      toggleExpanded,
    } = treeLogic;

    const { screenSize, responsiveSetting } = useGetScreenConfigTreeSelect({
      responsive,
      maxCount: maxCount ?? DEFAULT_MAX_COUNT,
    });

    const widthConstraints = React.useMemo(() => {
      const defaultMinWidth = screenSize === 'mobile' ? '0px' : '200px';
      const effectiveMinWidth = minWidth || defaultMinWidth;
      const effectiveMaxWidth = maxWidth || '100%';
      return {
        minWidth: effectiveMinWidth,
        maxWidth: effectiveMaxWidth,
        width: autoSize ? 'auto' : '100%',
      };
    }, [autoSize, maxWidth, minWidth, screenSize]);

    const handleSelectNode = React.useCallback(
      (id: string) => {
        toggleNode(id);
        if (!multiple) {
          // In single mode, close the popover and reset view state
          // (search value and expanded/collapsed state) after a selection.
          treeLogic.resetViewState();
          setIsPopoverOpen(false);
        }
      },
      [multiple, toggleNode, treeLogic]
    );
    const selectedValuesLength = selectedValues.length;

    const hasInitializedDefaultSelectAll = React.useRef(false);

    React.useEffect(() => {
      if (
        multiple &&
        defaultSelectAll &&
        !hasInitializedDefaultSelectAll.current &&
        rows.length > 0 &&
        selectedValuesLength === 0
      ) {
        toggleAll();
        hasInitializedDefaultSelectAll.current = true;
      }
    }, [multiple, defaultSelectAll, rows.length, selectedValuesLength, toggleAll]);

    const { shouldVirtualize, virtualizer, renderVirtualizedItem } = useTreeSelectVirtual({
      enabled: enableVirtualization,
      rows,
      selectionMap,
      listRef,
      estimateSize,
      optionLabelMaxWidth,
      onToggleNode: handleSelectNode,
      onToggleExpand: toggleExpanded,
      multiple,
      selectedId: !multiple && selectedValuesLength > 0 ? selectedValues[0] : undefined,
    });

    const treeSelectId = React.useId();
    const listboxId = `${treeSelectId}-listbox`;
    const triggerDescriptionId = `${treeSelectId}-description`;
    const selectedCountId = `${treeSelectId}-count`;

    const handlePopoverOpenChange = React.useCallback(
      (open: boolean) => {
        if (open) {
          suppressScrollOnFocus();
        } else {
          // When the popover closes (e.g. clicking the trigger again),
          // reset the search value and collapsed/expanded state so that
          // the next open starts from a clean view.
          treeLogic.resetViewState();
        }
        setIsPopoverOpen(open);
        onOpenChange?.(open);
      },
      [treeLogic, onOpenChange]
    );

    const handleFocus = React.useCallback(() => {
      if (buttonRef.current) {
        buttonRef.current.focus();
      }
    }, []);

    React.useImperativeHandle(
      ref,
      () => ({
        reset: () => {
          clear();
          treeLogic.resetViewState();
          setIsPopoverOpen(false);
        },
        getSelectedValues: () => selectedValues,
        setSelectedValues: (values: string[]) => {
          treeLogic.setSelectedValues(values);
        },
        clear: () => {
          clear();
        },
        focus: handleFocus,
      }),
      [clear, handleFocus, selectedValues, treeLogic]
    );

    const effectiveSearchable = searchable ?? true;

    return (
      <div className={cn('w-full min-w-[200px]', className)}>
        <Popover open={isPopoverOpen} onOpenChange={handlePopoverOpenChange} modal={modalPopover}>
          <div id={triggerDescriptionId} className="sr-only">
            Tree-select dropdown. Use arrow keys to navigate, Enter to select, and Escape to close.
          </div>
          <div id={selectedCountId} className="sr-only" aria-live="polite">
            {selectedValuesLength === 0
              ? 'No options selected'
              : `${selectedValuesLength} option${
                  selectedValuesLength === 1 ? '' : 's'
                } selected: ${selectedValues
                  .map((value) => getLabelForValue(value) ?? value)
                  .join(', ')}`}
          </div>

          <PopoverTrigger
            render={(triggerProps) => (
              <Button
                {...(triggerProps as React.ComponentPropsWithoutRef<typeof Button>)}
                ref={(node) => {
                  if (typeof triggerProps.ref === 'function') {
                    triggerProps.ref(node);
                  } else if (triggerProps.ref) {
                    (triggerProps.ref as React.RefObject<HTMLButtonElement | null>).current = node;
                  }
                  buttonRef.current = node;
                }}
                variant="outline"
                onClick={() => !disabled && handlePopoverOpenChange(!isPopoverOpen)}
                disabled={disabled}
                role="combobox"
                aria-expanded={isPopoverOpen}
                aria-haspopup="listbox"
                aria-controls={isPopoverOpen ? listboxId : undefined}
                aria-describedby={`${triggerDescriptionId} ${selectedCountId}`}
                aria-label={`Tree-select: ${selectedValuesLength} selected. ${placeholder}`}
                className={cn(
                  'flex h-auto min-h-8 items-center justify-between rounded-md border border-input bg-transparent px-0! py-1 text-xs shadow-xs outline-none transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[size=default]:h-8 data-[size=sm]:h-7 dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:hover:bg-input/50 [&_svg]:pointer-events-auto',
                  autoSize ? 'w-auto' : 'w-full',
                  responsiveSetting.compactMode && 'min-h-7 text-xs',
                  screenSize === 'mobile' && 'min-h-12 text-base',
                  disabled && 'cursor-not-allowed opacity-50',
                  triggerClassName
                )}
                style={{
                  ...widthConstraints,
                  maxWidth: `min(${widthConstraints.maxWidth}, 100%)`,
                }}
              >
                {selectedValuesLength > 0 ? (
                  <div className="flex min-w-0 flex-1 items-center justify-between overflow-hidden">
                    <div className="flex min-w-0 flex-wrap items-center gap-1 overflow-hidden">
                      {selectedValues
                        .slice(0, multiple ? responsiveSetting.maxCount : 1)
                        .map((value) => {
                          const label = getLabelForValue(value) ?? value;
                          if (!multiple) {
                            return (
                              <span
                                key={value}
                                className="mx-3 truncate text-xs"
                                style={{ maxWidth: badgeLabelMaxWidth }}
                              >
                                {label}
                              </span>
                            );
                          }

                          const effectiveBadgeAnimation =
                            animationConfig?.badgeAnimation ?? badgeAnimation ?? 'bounce';

                          const badgeClassName = cn(
                            treeSelectVariants({
                              variant,
                              badgeAnimation: effectiveBadgeAnimation,
                            }),
                            responsiveSetting.compactMode && 'px-1.5 py-0.5 text-xs',
                            screenSize === 'mobile' && 'max-w-[120px] truncate',
                            singleLine && 'shrink-0 whitespace-nowrap'
                          );

                          const badgeStyle: CSSProperties = {
                            animationDuration: `${animationConfig?.duration ?? animation ?? 0}s`,
                            animationDelay: `${animationConfig?.delay ?? 0}s`,
                          };

                          const iconClassName = cn(
                            'mr-2 h-4 w-4',
                            responsiveSetting.compactMode && 'mr-1 h-3 w-3'
                          );

                          return (
                            <SelectedTreeItemNode
                              key={value}
                              label={label}
                              badgeLabelMaxWidth={badgeLabelMaxWidth}
                              onRemove={() => toggleNode(value)}
                              badgeClassName={badgeClassName}
                              badgeStyle={badgeStyle}
                              iconClassName={iconClassName}
                              compactMode={responsiveSetting.compactMode}
                            />
                          );
                        })}
                      {multiple && selectedValuesLength > responsiveSetting.maxCount && (
                        <SelectedTreeItemNode
                          key="tree-select-more-indicator"
                          label={`+ ${selectedValuesLength - responsiveSetting.maxCount} more`}
                          badgeLabelMaxWidth={badgeLabelMaxWidth}
                          onRemove={() => {
                            const visible = selectedValues.slice(0, responsiveSetting.maxCount);
                            treeLogic.setSelectedValues(visible);
                          }}
                          badgeClassName={cn(
                            treeSelectVariants({
                              variant,
                              badgeAnimation:
                                animationConfig?.badgeAnimation ?? badgeAnimation ?? 'bounce',
                            }),
                            responsiveSetting.compactMode && 'px-1.5 py-0.5 text-xs',
                            singleLine && 'shrink-0 whitespace-nowrap'
                          )}
                          badgeStyle={{
                            animationDuration: `${animationConfig?.duration ?? animation ?? 0}s`,
                            animationDelay: `${animationConfig?.delay ?? 0}s`,
                          }}
                          compactMode={responsiveSetting.compactMode}
                        />
                      )}
                    </div>
                    {!disableClear && (
                      <div
                        role="button"
                        tabIndex={0}
                        onClick={(event) => {
                          event.stopPropagation();
                          clear();
                        }}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            event.stopPropagation();
                            clear();
                          }
                        }}
                        aria-label={`Clear all ${selectedValuesLength} selected options`}
                        className="mx-2 flex h-4 w-4 cursor-pointer items-center justify-center rounded-sm text-muted-foreground hover:text-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1"
                      >
                        <XIcon className="h-4 w-4" />
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="mx-auto flex min-w-0 flex-1 items-center">
                    <span className="mx-3 truncate text-muted-foreground text-xs">
                      {placeholder}
                    </span>
                  </div>
                )}
                <ChevronDown className="mx-2 h-4 shrink-0 cursor-pointer text-muted-foreground" />
              </Button>
            )}
          />

          <PopoverContent
            id={listboxId}
            role="listbox"
            aria-multiselectable={multiple}
            aria-label="Available options"
            className={cn('w-(--anchor-width) p-0', popoverClassName)}
            style={{
              maxHeight: popoverMaxHeight ?? (screenSize === 'mobile' ? '70vh' : '60vh'),
              touchAction: 'manipulation',
            }}
            align="start"
          >
            <Command shouldFilter={false}>
              {effectiveSearchable && (
                <CommandInput
                  placeholder="Search..."
                  value={searchValue}
                  onValueChange={setSearchValue}
                  aria-label="Search through available options"
                />
              )}
              <CommandList
                ref={handleListRef}
                className={cn(
                  'max-h-[40vh] overflow-y-auto',
                  screenSize === 'mobile' && 'max-h-[50vh]',
                  'overscroll-behavior-y-contain'
                )}
              >
                {(isAsyncMode && asyncData.isLoading && asyncData.options.length === 0) ||
                isLoading ? (
                  <div className="flex items-center justify-center gap-2 py-6 text-xs">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span>{loadingText}</span>
                  </div>
                ) : (
                  <>
                    {searchValue && rows.length === 0 && (
                      <CommandEmpty>{emptyIndicator || 'No results found.'}</CommandEmpty>
                    )}

                    {!disableSelectAll && multiple && !searchValue && rows.length > 0 && (
                      <CommandGroup>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="w-full justify-start px-2 text-xs"
                          onClick={() => toggleAll()}
                        >
                          <CheckIcon className="mr-2 h-4 w-4" />
                          Select All
                        </Button>
                        <CommandSeparator />
                      </CommandGroup>
                    )}

                    {shouldVirtualize ? (
                      <CommandGroup>
                        <div
                          style={{
                            height: `${virtualizer.getTotalSize()}px`,
                            width: '100%',
                            position: 'relative',
                          }}
                        >
                          {virtualizer.getVirtualItems().map(renderVirtualizedItem)}
                        </div>
                      </CommandGroup>
                    ) : (
                      <CommandGroup>
                        {rows.map((row) => {
                          const selection = selectionMap[row.id];
                          const baseIndent = 8;
                          const indent = row.depth * 16 + baseIndent;
                          const isDisabled = selection?.disabled ?? false;
                          const isParent = !row.isLeaf;
                          const isSelected = multiple
                            ? !!selection?.checked
                            : selectedValuesLength > 0 && selectedValues[0] === row.id;
                          return (
                            <CommandItem
                              key={row.id}
                              value={row.id}
                              onSelect={() => handleSelectNode(row.id)}
                              role="option"
                              aria-selected={isSelected}
                              aria-disabled={isDisabled}
                              disabled={isDisabled}
                              className={cn(
                                'cursor-pointer',
                                !multiple &&
                                  isSelected &&
                                  'bg-primary/5 font-medium text-foreground',
                                isDisabled && 'cursor-not-allowed opacity-50'
                              )}
                            >
                              <div
                                className="flex w-full items-center"
                                style={{ paddingLeft: `${indent}px` }}
                              >
                                <span
                                  className="mr-1 flex h-4 w-4 items-center justify-center"
                                  aria-hidden="true"
                                  onClick={(event) => {
                                    event.stopPropagation();
                                    if (isParent) {
                                      toggleExpanded(row.id);
                                    }
                                  }}
                                >
                                  {isParent ? (
                                    row.isExpanded ? (
                                      <ChevronDown className="h-3 w-3" />
                                    ) : (
                                      <ChevronRight className="h-3 w-3" />
                                    )
                                  ) : null}
                                </span>
                                {multiple && (
                                  <div
                                    className={cn(
                                      'mr-2 flex h-4 w-4 items-center justify-center rounded-sm border border-primary',
                                      selection?.checked
                                        ? 'bg-primary text-primary-foreground'
                                        : selection?.indeterminate
                                          ? 'bg-primary/10 text-primary-foreground'
                                          : 'opacity-50 [&_svg]:invisible'
                                    )}
                                    aria-hidden="true"
                                  >
                                    {selection?.indeterminate ? (
                                      <MinusIcon className="h-3 w-3 text-white" />
                                    ) : (
                                      <CheckIcon className="h-4 w-4 text-white" />
                                    )}
                                  </div>
                                )}
                                {row.node.icon && (
                                  <span
                                    className="mr-2 flex h-4 w-4 items-center justify-center"
                                    aria-hidden="true"
                                  >
                                    {row.node.icon}
                                  </span>
                                )}
                                <LongText
                                  maxWidth={optionLabelMaxWidth}
                                  className="text-xs leading-normal"
                                >
                                  {row.node.title}
                                </LongText>
                              </div>
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    )}

                    {isAsyncMode && asyncData.hasMore && !asyncData.isLoading && (
                      <div
                        ref={asyncData.observerTarget}
                        className="flex items-center justify-center py-2"
                      >
                        {asyncData.isLoadingMore && (
                          <div className="flex items-center gap-2 text-muted-foreground text-xs">
                            <Loader2 className="h-3 w-3 animate-spin" />
                            <span>{loadingMoreText}</span>
                          </div>
                        )}
                      </div>
                    )}
                  </>
                )}

                <CommandSeparator />
                <CommandGroup>
                  <div className="flex items-center justify-between">
                    {selectedValuesLength > 0 && !disableClear && (
                      <>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="flex-1 justify-center text-xs"
                          onClick={() => clear()}
                        >
                          Clear
                        </Button>
                        <Separator orientation="vertical" className="flex h-full min-h-6" />
                      </>
                    )}
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="flex-1 justify-center text-xs"
                      onClick={() => setIsPopoverOpen(false)}
                    >
                      Close
                    </Button>
                  </div>
                </CommandGroup>
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      </div>
    );
  }
);

TreeSelectInner.displayName = 'TreeSelectInner';

/**
 * Single-value tree select component.
 *
 * Selects exactly one value. No `multiple` prop needed.
 *
 * @example
 * ```tsx
 * const [value, setValue] = useState<string | null>(null);
 * <TreeSelect value={value} onChange={setValue} treeData={data} />
 * ```
 */
export const TreeSelect = React.forwardRef<TreeSelectRef, TreeSelectProps>(
  ({ value, defaultValue, onChange, ...rest }, ref) => {
    const innerValue = value != null ? [value] : value === null ? [] : undefined;
    const innerDefault =
      defaultValue != null ? [defaultValue] : defaultValue === null ? [] : undefined;

    const handleChange = onChange
      ? (nextValues: string[], selectedNodes: TreeSelectItem[]) => {
          const nextValue = nextValues.length > 0 ? nextValues[0] : null;
          onChange(nextValue ?? null, selectedNodes[0]);
        }
      : undefined;

    return (
      <TreeSelectInner
        ref={ref}
        multiple={false}
        value={innerValue}
        defaultValue={innerDefault}
        onChange={handleChange}
        {...rest}
      />
    );
  }
);

TreeSelect.displayName = 'TreeSelect';

/**
 * Multi-value tree select component.
 *
 * Selects multiple values with checkboxes, badges, select-all, etc.
 * No `multiple` prop needed.
 *
 * @example
 * ```tsx
 * const [values, setValues] = useState<string[]>([]);
 * <TreeMultipleSelect value={values} onChange={setValues} treeData={data} />
 * ```
 */
export const TreeMultipleSelect = React.forwardRef<TreeSelectRef, TreeMultipleSelectProps>(
  ({ value, defaultValue, onChange, ...rest }, ref) => {
    const handleChange = onChange
      ? (nextValues: string[], selectedNodes: TreeSelectItem[]) => {
          onChange(nextValues ?? [], selectedNodes);
        }
      : undefined;

    return (
      <TreeSelectInner
        ref={ref}
        multiple={true}
        value={value}
        defaultValue={defaultValue}
        onChange={handleChange}
        {...rest}
      />
    );
  }
);

TreeMultipleSelect.displayName = 'TreeMultipleSelect';

'use client';

import type { ScreenSize } from '../../../../types/screen';
import React from 'react';
import type { ResponsiveConfig } from '../types';

const getResponsiveSettings = (
  responsive: ResponsiveConfig,
  maxCount: number,
  screenSize: ScreenSize
) => {
  if (!responsive) {
    return {
      maxCount: maxCount,
      hideIcons: false,
      compactMode: false,
    };
  }
  if (responsive === true) {
    const defaultResponsive = {
      mobile: { maxCount: 2, hideIcons: false, compactMode: true },
      tablet: { maxCount: 4, hideIcons: false, compactMode: false },
      desktop: { maxCount: 6, hideIcons: false, compactMode: false },
    };
    const currentSettings = defaultResponsive[screenSize];
    return {
      maxCount: currentSettings?.maxCount ?? maxCount,
      hideIcons: currentSettings?.hideIcons ?? false,
      compactMode: currentSettings?.compactMode ?? false,
    };
  }
  const currentSettings = responsive[screenSize];
  return {
    maxCount: currentSettings?.maxCount ?? maxCount,
    hideIcons: currentSettings?.hideIcons ?? false,
    compactMode: currentSettings?.compactMode ?? false,
  };
};

type UseGetScreenSizeProps = {
  responsive: ResponsiveConfig | undefined;
  maxCount: number;
};

export function useGetScreenConfigTreeSelect(props: UseGetScreenSizeProps) {
  const { responsive, maxCount } = props;
  const [screenSize, setScreenSize] = React.useState<ScreenSize>('desktop');

  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 640) {
        setScreenSize('mobile');
      } else if (width < 1024) {
        setScreenSize('tablet');
      } else {
        setScreenSize('desktop');
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('resize', handleResize);
      }
    };
  }, []);

  const responsiveSetting = getResponsiveSettings(responsive ?? false, maxCount, screenSize);

  return {
    screenSize,
    responsiveSetting,
  };
}

import * as React from 'react';
import { useControlledState } from '../../../../hooks/use-controlled-state';
import { useInfiniteScroll } from '../../../../hooks/use-infinite-scroll';
import { useDebouncedValue } from '../../../../hooks/use-debounced-value';
import type { TreeSelectItem, TreeSelectInnerProps } from '../types';

type NormalizedId = string;

export type TreeSelectRow = {
  id: NormalizedId;
  node: TreeSelectItem;
  depth: number;
  parentId?: NormalizedId;
  isLeaf: boolean;
  isExpanded: boolean;
};

export type SelectionState = {
  checked: boolean;
  indeterminate: boolean;
  disabled: boolean;
};

export type UseTreeSelectLogicResult = {
  /** Controlled/uncontrolled selected values (array contract). */
  selectedValues: string[];
  setSelectedValues: (values: string[]) => void;

  /** Async mode flag and data (when loadOptions is provided). */
  isAsyncMode: boolean;
  asyncData:
    | ReturnType<typeof useInfiniteScroll<TreeSelectItem>>
    | {
        options: TreeSelectItem[];
        search: string;
        setSearch: (value: string) => void;
        page: number;
        hasMore: boolean;
        isLoading: boolean;
        isLoadingMore: boolean;
        observerTarget: React.Ref<HTMLDivElement>;
        fetchOptions: () => Promise<void>;
        reset: () => void;
      };

  /** Effective search value and setter (local or async). */
  searchValue: string;
  setSearchValue: (value: string) => void;

  /** Flattened rows for rendering / virtualization. */
  rows: TreeSelectRow[];

  /** Map of node id to selection state (checked/indeterminate/disabled). */
  selectionMap: Record<NormalizedId, SelectionState>;

  /** Toggle a single node with cascade behavior. */
  toggleNode: (id: NormalizedId) => void;

  /** Toggle all selectable nodes. */
  toggleAll: () => void;

  /** Clear all selections. */
  clear: () => void;

  /** Utility: get display label for a selected value. */
  getLabelForValue: (value: string) => string | undefined;

  /** Expand/collapse a single node. */
  toggleExpanded: (id: NormalizedId) => void;

  /** Reset view-related state such as search and expanded nodes. */
  resetViewState: () => void;
};

const normalizeId = (value: string): NormalizedId => value;

type BuildMapsResult = {
  rows: TreeSelectRow[];
  byId: Map<NormalizedId, TreeSelectItem>;
  parents: Map<NormalizedId, NormalizedId | undefined>;
  children: Map<NormalizedId, NormalizedId[]>;
};

const buildTreeMaps = (tree: TreeSelectItem[], expandedIds: Set<NormalizedId>): BuildMapsResult => {
  const rows: TreeSelectRow[] = [];
  const byId = new Map<NormalizedId, TreeSelectItem>();
  const parents = new Map<NormalizedId, NormalizedId | undefined>();
  const children = new Map<NormalizedId, NormalizedId[]>();

  const visit = (
    nodes: TreeSelectItem[] | undefined,
    depth: number,
    parentId?: NormalizedId,
    parentVisible = true
  ) => {
    if (!nodes || nodes.length === 0) return;
    for (const node of nodes) {
      const id = normalizeId(node.value);
      byId.set(id, node);
      parents.set(id, parentId);

      const childNodes = node.children ?? [];
      const childIds: NormalizedId[] = childNodes.map((c) => normalizeId(c.value));
      children.set(id, childIds);

      const isExpanded = childNodes.length > 0 ? expandedIds.has(id) : false;
      const isLeaf = childNodes.length === 0;
      const isVisible = depth === 0 || parentVisible;

      if (isVisible) {
        rows.push({
          id,
          node,
          depth,
          parentId,
          isLeaf,
          isExpanded,
        });
      }

      const nextParentVisible = isVisible && isExpanded;
      visit(childNodes, depth + 1, id, nextParentVisible);
    }
  };

  visit(tree, 0, undefined, true);

  return { rows, byId, parents, children };
};

const collectDescendantLeaves = (
  id: NormalizedId,
  children: Map<NormalizedId, NormalizedId[]>
): NormalizedId[] => {
  const result: NormalizedId[] = [];
  const stack: NormalizedId[] = [id];

  while (stack.length) {
    const current = stack.pop();
    if (current === undefined) {
      continue;
    }
    const childIds = children.get(current) ?? [];

    if (childIds.length === 0) {
      result.push(current);
    } else {
      for (const child of childIds) {
        stack.push(child);
      }
    }
  }

  return result;
};

const buildSelectionMap = (
  allIds: NormalizedId[],
  children: Map<NormalizedId, NormalizedId[]>,
  byId: Map<NormalizedId, TreeSelectItem>,
  selected: Set<NormalizedId>
): Record<NormalizedId, SelectionState> => {
  const map: Record<NormalizedId, SelectionState> = {};

  const computeState = (id: NormalizedId): SelectionState => {
    const existing = map[id];
    if (existing) {
      return existing;
    }

    const node = byId.get(id);
    const disabled = Boolean(node?.disabled || node?.disableCheckbox);
    const childIds = children.get(id) ?? [];

    if (childIds.length === 0) {
      const checked = selected.has(id);
      const state: SelectionState = { checked, indeterminate: false, disabled };
      map[id] = state;
      return state;
    }

    let allChildrenChecked = true;
    let anyChildChecked = false;

    for (const childId of childIds) {
      const childState = computeState(childId);
      if (childState.checked || childState.indeterminate) {
        anyChildChecked = true;
      }
      if (!childState.checked || childState.indeterminate) {
        allChildrenChecked = false;
      }
    }

    const checked = allChildrenChecked && !disabled;
    const indeterminate = !checked && anyChildChecked;
    const state: SelectionState = { checked, indeterminate, disabled };
    map[id] = state;
    return state;
  };

  for (const id of allIds) {
    if (!map[id]) {
      map[id] = computeState(id);
    }
  }

  return map;
};

type InternalTreeSelectProps = {
  treeData: TreeSelectItem[];
  value?: string[] | string | null;
  defaultValue?: string[] | string | null;
  multiple?: boolean;
  loadOptions?: TreeSelectInnerProps['loadOptions'];
  debounceMs?: TreeSelectInnerProps['debounceMs'];
  defaultExpandAll?: boolean;
  observerRoot?: Element | Document | null;
  isOpen?: boolean;
  /**
   * Internal normalized `onChange` that always receives `string[]`
   * and the corresponding `TreeSelectItem[]`, regardless of single
   * or multiple mode.
   */
  onChange?: (value: string[], selectedNodes: TreeSelectItem[]) => void;
};

const normalizeToArray = (
  value: InternalTreeSelectProps['value'],
  multiple: boolean
): string[] | undefined => {
  if (multiple) {
    return value as string[] | undefined;
  }
  const single = (value as string | null | undefined) ?? null;
  if (single == null) return [];
  return [single];
};

const normalizeDefaultToArray = (
  defaultValue: InternalTreeSelectProps['defaultValue'],
  multiple: boolean
): string[] | undefined => {
  if (multiple) {
    return defaultValue as string[] | undefined;
  }
  const single = (defaultValue as string | null | undefined) ?? null;
  if (single == null) return [];
  return [single];
};

export function useTreeSelectLogic(props: InternalTreeSelectProps): UseTreeSelectLogicResult {
  const {
    treeData,
    value,
    defaultValue,
    onChange,
    loadOptions,
    debounceMs = 300,
    multiple = true,
    defaultExpandAll = false,
    observerRoot = null,
    isOpen = true,
  } = props;

  const normalizedValue = normalizeToArray(value, multiple);
  const normalizedDefaultValue = normalizeDefaultToArray(defaultValue, multiple);

  const [selectedValues, setSelectedValues] = useControlledState<string[]>({
    value: normalizedValue,
    defaultValue: normalizedDefaultValue ?? [],
    // We intentionally do not forward `onChange` directly so that we can
    // also provide the resolved `TreeSelectItem[]` to callers.
    onChange: (nextValues) => {
      const safeValues = nextValues ?? [];
      // `byId` is populated after the first render and kept stable via `useMemo`,
      // so it's safe to read here when changes actually occur (post-mount).
      const selectedNodes: TreeSelectItem[] = safeValues
        .map((id) => byId.get(id))
        .filter((node): node is TreeSelectItem => Boolean(node));
      onChange?.(safeValues, selectedNodes);
    },
  });

  const isAsyncMode = Boolean(loadOptions);

  const infiniteScroll = useInfiniteScroll<TreeSelectItem>({
    loadOptions: async (search, page) => {
      if (!loadOptions) {
        return { options: [], hasMore: false };
      }
      return loadOptions(search, page);
    },
    debounceMs,
    enabled: isAsyncMode && isOpen,
    initialSearch: '',
    observerRoot,
  });

  const asyncData = isAsyncMode
    ? infiniteScroll
    : {
        options: treeData,
        search: '',
        setSearch: () => {},
        page: 1,
        hasMore: false,
        isLoading: false,
        isLoadingMore: false,
        error: null,
        observerTarget: () => {},
        fetchOptions: async () => {},
        reset: () => {},
      };

  // NOTE:
  // - In async mode, `asyncData.options` is expected to already contain
  //   hierarchical `TreeSelectItem[]` with `children` populated when you
  //   want true tree behaviour (expand/collapse, indentation).
  // - If your `loadOptions` implementation returns a flat list of items
  //   with no `children`, the component will intentionally behave like a
  //   flat infinite list instead of a tree.
  const [localSearchValue, setLocalSearchValue] = React.useState('');
  const searchValue = isAsyncMode ? asyncData.search : localSearchValue;
  const setSearchValue = (val: string) => {
    if (isAsyncMode) {
      asyncData.setSearch(val);
    } else {
      setLocalSearchValue(val);
    }
  };

  /**
   * Debounced search value used for expensive operations such as
   * filtering the tree. This keeps the input responsive while
   * avoiding re-filtering on every keystroke.
   */
  const debouncedSearch = useDebouncedValue(searchValue, debounceMs);

  const createInitialExpandedIds = (
    source: TreeSelectItem[],
    expandAll: boolean
  ): Set<NormalizedId> => {
    // Always expand root nodes so the first level is visible.
    const initial = new Set(source.map((n) => normalizeId(n.value)));

    // Optionally expand all expandable nodes (those with children).
    if (expandAll) {
      const visit = (nodes: TreeSelectItem[] | undefined) => {
        if (!nodes) return;
        for (const node of nodes) {
          const id = normalizeId(node.value);
          if (node.children && node.children.length > 0) {
            initial.add(id);
            visit(node.children);
          }
        }
      };
      visit(source);
    }

    return initial;
  };

  const [expandedIds, setExpandedIds] = React.useState<Set<NormalizedId>>(() => {
    const source = (isAsyncMode ? asyncData.options : treeData) ?? [];
    return createInitialExpandedIds(source, defaultExpandAll);
  });

  const toggleExpanded = React.useCallback((id: NormalizedId) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const resetViewState = React.useCallback(() => {
    // Reset search value and avoid triggering destructive option replacement in
    // async mode (e.g. close/reopen flow).
    if (isAsyncMode) {
      asyncData.setSearch('', { skipFetch: true });
    } else {
      setLocalSearchValue('');
    }

    // Reset expanded state back to the initial configuration.
    const source = (isAsyncMode ? asyncData.options : treeData) ?? [];
    setExpandedIds(createInitialExpandedIds(source, defaultExpandAll));
  }, [isAsyncMode, asyncData, treeData, defaultExpandAll]);

  const effectiveTree = React.useMemo<TreeSelectItem[]>(() => {
    const source = (isAsyncMode ? asyncData.options : treeData) ?? [];
    if (!debouncedSearch) return source;

    const matches = (node: TreeSelectItem): boolean => {
      const titleText =
        typeof node.title === 'string'
          ? node.title
          : // Fallback for non-string titles: rely on value
            '';
      const valueText = String(node.value);
      const query = debouncedSearch.toLowerCase();
      return titleText.toLowerCase().includes(query) || valueText.toLowerCase().includes(query);
    };

    const filterTree = (nodes: TreeSelectItem[] | undefined): TreeSelectItem[] => {
      if (!nodes) return [];
      const result: TreeSelectItem[] = [];
      for (const node of nodes) {
        const childFiltered = filterTree(node.children);
        if (matches(node) || childFiltered.length > 0) {
          result.push({
            ...node,
            children: childFiltered.length > 0 ? childFiltered : node.children,
          });
        }
      }
      return result;
    };

    return filterTree(source);
  }, [isAsyncMode, asyncData.options, treeData, debouncedSearch]);

  const {
    rows,
    byId,
    children: childrenMap,
  } = React.useMemo(() => buildTreeMaps(effectiveTree, expandedIds), [effectiveTree, expandedIds]);

  const selectedSet = React.useMemo(() => new Set<string>(selectedValues ?? []), [selectedValues]);

  const selectionMap = React.useMemo(
    () =>
      buildSelectionMap(
        rows.map((r) => r.id),
        childrenMap,
        byId,
        selectedSet
      ),
    [rows, childrenMap, byId, selectedSet]
  );

  const toggleNode = React.useCallback(
    (id: NormalizedId) => {
      const node = byId.get(id);
      if (!node || node.disabled || node.disableCheckbox) return;

      if (!multiple) {
        const next = new Set<string>(selectedSet);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.clear();
          next.add(id);
        }
        setSelectedValues(Array.from(next));
      } else {
        const affectedLeafIds = collectDescendantLeaves(id, childrenMap);
        const allSelected = affectedLeafIds.every((nid) => selectedSet.has(nid));

        const next = new Set(selectedSet);
        if (allSelected) {
          for (const nid of affectedLeafIds) {
            next.delete(nid);
          }
        } else {
          for (const nid of affectedLeafIds) {
            const n = byId.get(nid);
            if (n && !n.disabled && !n.disableCheckbox) {
              next.add(nid);
            }
          }
        }

        setSelectedValues(Array.from(next));
      }
    },
    [byId, childrenMap, selectedSet, setSelectedValues, multiple]
  );

  const clear = React.useCallback(() => {
    setSelectedValues([]);
  }, [setSelectedValues]);

  const toggleAll = React.useCallback(() => {
    const selectableLeafIds: NormalizedId[] = [];

    for (const [id, node] of byId) {
      const childIds = childrenMap.get(id) ?? [];
      const isLeaf = childIds.length === 0;
      if (isLeaf && !node.disabled && !node.disableCheckbox) {
        selectableLeafIds.push(id);
      }
    }

    const allSelected =
      selectableLeafIds.length > 0 && selectableLeafIds.every((id) => selectedSet.has(id));

    if (allSelected) {
      clear();
    } else {
      setSelectedValues(selectableLeafIds);
    }
  }, [byId, childrenMap, selectedSet, clear, setSelectedValues]);

  const getLabelForValue = React.useCallback(
    (valueStr: string): string | undefined => {
      const node = byId.get(valueStr);
      if (!node) return undefined;
      if (typeof node.title === 'string') return node.title;
      return String(node.value);
    },
    [byId]
  );

  return {
    selectedValues: selectedValues ?? [],
    setSelectedValues: (vals: string[]) => setSelectedValues(vals),
    isAsyncMode,
    asyncData,
    searchValue,
    setSearchValue,
    rows,
    selectionMap,
    toggleNode,
    toggleAll,
    clear,
    getLabelForValue,
    toggleExpanded,
    resetViewState,
  };
}

import type * as React from 'react';
import { useVirtualizer, type VirtualItem } from '@tanstack/react-virtual';
import { ChevronRight, ChevronDown, CheckIcon, MinusIcon } from 'lucide-react';

import { CommandItem } from '../../../ui/forms/command';
import { cn } from '../../../../lib/utils';
import { LongText } from '../../long-text';
import type { SelectionState, TreeSelectRow } from './use-tree-select-logic';

type UseTreeSelectVirtualProps = {
  enabled?: boolean;
  rows: TreeSelectRow[];
  selectionMap: Record<string, SelectionState>;
  listRef: React.RefObject<HTMLDivElement | null>;
  estimateSize?: number;
  optionLabelMaxWidth?: string;
  onToggleNode: (id: string) => void;
  onToggleExpand: (id: string) => void;
  multiple?: boolean;
  selectedId?: string;
};

export function useTreeSelectVirtual({
  enabled = false,
  rows,
  selectionMap,
  listRef,
  estimateSize = 32,
  optionLabelMaxWidth = '100%',
  onToggleNode,
  onToggleExpand,
  multiple = true,
  selectedId,
}: UseTreeSelectVirtualProps) {
  const shouldVirtualize = enabled;

  const virtualizer = useVirtualizer({
    count: shouldVirtualize ? rows.length : 0,
    getScrollElement: () => listRef.current,
    estimateSize: () => estimateSize,
    overscan: 8,
  });

  const renderVirtualizedItem = (virtualItem: VirtualItem) => {
    const row = rows[virtualItem.index];
    if (!row) return null;

    const selection = selectionMap[row.id];
    const style: React.CSSProperties = {
      position: 'absolute',
      top: 0,
      left: 0,
      width: '100%',
      height: `${virtualItem.size}px`,
      transform: `translateY(${virtualItem.start}px)`,
    };

    // Keep base padding consistent with non-virtualized TreeSelect rows
    const baseIndent = 8;
    const indent = row.depth * 16 + baseIndent;
    const isDisabled = selection?.disabled ?? false;
    const isSelected = multiple ? !!selection?.checked : selectedId === row.id;

    return (
      <CommandItem
        key={row.id}
        value={row.id}
        onSelect={() => onToggleNode(row.id)}
        role="option"
        aria-selected={selection?.checked}
        aria-disabled={isDisabled}
        style={style}
        className={cn(
          'cursor-pointer',
          !multiple && isSelected && 'bg-primary/5 font-medium text-foreground',
          isDisabled && 'cursor-not-allowed opacity-50'
        )}
        disabled={isDisabled}
      >
        <div className="flex w-full items-center" style={{ paddingLeft: `${indent}px` }}>
          <span
            className="mr-1 flex h-4 w-4 items-center justify-center"
            aria-hidden="true"
            onClick={(e) => {
              if (!row.isLeaf) {
                e.stopPropagation();
                onToggleExpand(row.id);
              }
            }}
          >
            {!row.isLeaf ? (
              row.isExpanded ? (
                <ChevronDown className="h-3 w-3" />
              ) : (
                <ChevronRight className="h-3 w-3" />
              )
            ) : null}
          </span>
          {multiple && (
            <div
              className={cn(
                'mr-2 flex h-4 w-4 items-center justify-center rounded-sm border border-primary',
                selection?.checked
                  ? 'bg-primary text-primary-foreground'
                  : selection?.indeterminate
                    ? 'bg-primary/10 text-primary-foreground'
                    : 'opacity-50 [&_svg]:invisible'
              )}
              aria-hidden="true"
            >
              {selection?.indeterminate ? (
                <MinusIcon className="h-3 w-3 text-white" />
              ) : (
                <CheckIcon className="h-4 w-4 text-white" />
              )}
            </div>
          )}
          {row.node.icon && (
            <span className="mr-2 flex h-4 w-4 items-center justify-center" aria-hidden="true">
              {row.node.icon}
            </span>
          )}
          <LongText maxWidth={optionLabelMaxWidth} className="text-xs leading-normal">
            {row.node.title}
          </LongText>
        </div>
      </CommandItem>
    );
  };

  return {
    shouldVirtualize,
    virtualizer,
    renderVirtualizedItem,
  };
}

export { TreeSelect, TreeMultipleSelect } from './component';
